import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"BOSS: Benchmark for Observation Space Shift in Long-Horizon Task","description":"","frontmatter":{"title":"BOSS: Benchmark for Observation Space Shift in Long-Horizon Task","arxiv":"2502.15679","date":"2025-02-21","authors":"Yue Yang, Linfeng Zhao, Mingyu Ding, Gedas Bertasius, Daniel Szafir","categories":"cs.RO, cs.AI, cs.CV","topics":"长时程操作, 技能链, 机器人基准","outline":[2,2]},"headers":[],"relativePath":"papers/2502.15679.md","filePath":"papers/2502.15679.md","lastUpdated":null}'),e={name:"papers/2502.15679.md"};function l(r,s,i,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="boss-benchmark-for-observation-space-shift-in-long-horizon-task" tabindex="-1">BOSS: Benchmark for Observation Space Shift in Long-Horizon Task <a class="header-anchor" href="#boss-benchmark-for-observation-space-shift-in-long-horizon-task" aria-label="Permalink to &quot;BOSS: Benchmark for Observation Space Shift in Long-Horizon Task&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2502.15679" target="_blank" rel="noreferrer">2502.15679</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-02-21</td></tr><tr><td><strong>作者</strong></td><td>Yue Yang, Linfeng Zhao, Mingyu Ding, Gedas Bertasius, Daniel Szafir</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把技能链失败的一个被忽略的原因命名为&quot;观测空间偏移&quot;——前序技能改变了对当前技能<strong>符号上无关</strong>的谓词，却移动了视觉策略的输入分布——并用 LIBERO 上可自动批量生成的三级挑战把它量化，同时证明单靠扩充视觉多样化演示补不上这个洞。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>模仿学习只擅长短程任务，长程任务的标准解法是分层：让一个规划器（TAMP 或 LLM）排出技能序列，每个技能由独立训练的视觉运动策略执行。这条路线的隐含前提是<strong>技能可以像函数一样组合</strong>——只要前一个技能的终止状态落在后一个技能的初始状态集合里，链就能跑通。</p><p>论文指出的问题是：对<strong>视觉输入</strong>的策略来说，这个前提以一种此前没被明确命名的方式失效。例子很干净：<code>PlaceObject(potato, bowl)</code> 执行完之后，碗里多了一个土豆；而 <code>MoveContainer(bowl, cabinet)</code> 训练时看到的碗全是空的。从符号规划的角度看，<code>In(potato, bowl)</code> 既不在 <code>MoveContainer</code> 的前置条件里也不在效果里，因而是&quot;无关&quot;的；但它明明白白出现在图像里，于是策略的观测分布被移动了。作者把这个现象叫 Observation Space Shift（OSS）。</p><p>为什么重要：如果 OSS 普遍存在且严重，那么&quot;用一堆预训练技能拼长程任务&quot;这个当前主流的工程范式就有系统性的成功率上限，而且这个上限不会随着规划器变强而提高。更麻烦的是它随链长累积——每多执行一个技能，后续技能面对的观测就更偏一点。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>技能衔接问题本身研究得不少，可以分两条线。<strong>离线路线</strong>学一个 transition policy，把前一个技能的终止状态推回到后一个技能的初始状态分布里（Lee 等 2019 用邻近度预测器、对抗逆强化学习、目标条件策略等）。<strong>在线路线</strong>反过来改策略：或扩大后继技能的初始状态集合，或用对抗框架把前序技能的终止分布正则到后继技能的初始分布上（Lee 等 2021），或用对比学习造辅助奖励，或干脆联合优化整条链（Chen 等 2023）。</p><p>论文对它们的批评是精确的，而且指出了一个共同的盲点：<strong>这些工作的观测空间里都没有视觉</strong>，因此各自的假设在视觉设定下会失效。离线方法假设&quot;目标技能的初始状态总是可达&quot;——在视觉设定下这要求撤销已完成的技能（把土豆从碗里拿出来），逻辑上就是错的。在线方法假设&quot;策略可以持续微调&quot;——但视觉 OSS 在<strong>每一次</strong>技能切换都可能发生，反复微调的算力开销不现实。至于机器人基准：Meta-World、RLBench、Robomimic、ManiSkill2 不针对长程；CALVIN、FurnitureBench、RoboCasa、LoHoRavens 有长程但不针对衔接。LIBERO 因为任务由 PDDL 描述、便于程序化改写，被选作底座。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 2024 年，一个做分层模仿学习的人会先观察到一个日常现象：单个技能测起来好好的，串成链就掉得离谱，而且掉的地方常常不是&quot;手没对准&quot;，而是策略从一开始就往错误方向动。第一反应通常归因于<strong>动力学层面</strong>的衔接——机械臂停在了奇怪的位形上。但只要在每个技能之间把机器人复位到中性姿态，这个解释就被排除了，掉分仍然存在。</p><p>于是剩下的差异只可能在观测里。这时 TAMP 的形式化提供了一个现成的、可以把问题说清楚的语言：算子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2222em;"></span><span class="mord text"><span class="mord texttt">op</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⟨</span><span class="mord text"><span class="mord texttt">Pre</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">Eff</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">⟩</span></span></span></span> 只关心与可行性有关的谓词，其余谓词被抽象掉。抽象掉的东西在符号层面确实无关，但<strong>视觉策略读的是像素，不是符号</strong>。这一步是整篇论文的关键转折：把&quot;符号相关性&quot;与&quot;感知相关性&quot;分开，OSS 就自动被定义出来了。</p><p>接下来是可操作性问题。要研究它就得能批量制造 OSS，而 LIBERO 的任务恰好由 PDDL 文件定义，谓词是显式的、可程序化修改的。于是&quot;规则化自动改写生成器&quot;这个工具几乎是被数据格式送到手上的。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>符号规划把状态抽象成谓词集合，只保留与可行性有关的那些；视觉策略却把整张图当输入，抽象掉的谓词照样以像素形式进来。所以只要前序技能改变了任何一个&quot;符号上无关但视觉上可见&quot;的谓词，后继技能就被推出了它的训练分布——而这恰恰是技能链每一步都在做的事。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 <code>OpenDrawer(cabinet) → PlaceObject(potato, bowl) → MoveContainer(bowl, cabinet)</code> 这条链为例：</p><ol><li><strong>原子任务集</strong>。从 LIBERO-100 里剔除多技能任务，保留 44 个单技能任务，覆盖 12 个操作场景。这批任务代表&quot;不受 OSS 影响&quot;的对照组。</li><li><strong>RAMG（Rule-based Automatic Modification Generator）</strong>。直接改 PDDL：(a) 重新摆放已有物体或往指定区域加入新物体；(b) 翻转固定设施状态（如 <code>DrawerOpen</code>）；(c) 修改容纳关系（如 <code>In(potato, bowl)</code>）。改写要满足动力学约束（新物体不干扰 <code>Pre</code>/<code>Eff</code>）与逻辑一致性（不能同时成立 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">¬</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）。单次改写即可从 44 个任务生成最多 1727 个变体。</li><li><strong>三级挑战</strong>。BOSS-C1（44 个任务 + 44 个单次改写变体）测单步偏移；BOSS-C2 用 RAMG 迭代两次/三次生成累积偏移；BOSS-C3 手工组合出 10 条三技能链，<strong>每个技能之间把机器人复位到中性位姿</strong>，以剔除动力学衔接因素。</li><li><strong>评测</strong>。四个基线：BC-RESNET-RNN、BC-RESNET-T、BC-VIT-T（均用 BERT 编码指令、GMM 动作头）与 OpenVLA。为对齐 OpenVLA 的观测空间，BC 侧只用第三人称相机 + 7 自由度关节角 + 2 自由度夹爪，<strong>去掉腕部相机</strong>。动作为 7 维相对笛卡尔位移，20 Hz，三个随机种子取平均。</li><li><strong>数据增广对照</strong>。用 RAMG 造出 1727 个改写任务，在对应环境里重放原演示、滤掉失败的重放，得到 57,000 条轨迹（约为原始 2,000 条的 30 倍）——<strong>轨迹本身不变，只有视觉内容变了</strong>——再重训（BC）或微调（OpenVLA）。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>形式化本身就是这篇论文的主要理论贡献。环境是 POMDP <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⟨</span><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0794em;">Z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mclose">⟩</span></span></span></span>，策略 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord mathcal">A</span><span class="mclose">)</span></span></span></span> 只能看到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0794em;">Z</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。谓词 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">}</span></span></span></span> 是状态空间上的二值分类器。给定算子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2222em;"></span><span class="mord text"><span class="mord texttt">op</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⟨</span><span class="mord text"><span class="mord texttt">Pre</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord texttt">Eff</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">⟩</span></span></span></span>，谓词 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 被称为<strong>无关</strong>当且仅当</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mord"><span class="mrel">∈</span></span><span class="mord vbox"><span class="thinbox"><span class="llap"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="inner"><span class="mord"><span class="mord">/</span><span class="mspace" style="margin-right:0.0556em;"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6111em;"></span><span class="mord text"><span class="mord texttt">Pre</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∪</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6111em;"></span><span class="mord text"><span class="mord texttt">Eff</span></span></span></span></span></span></p><p>OSS 就是：无关谓词的改变通过 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0794em;">Z</span></span></span></span> 进入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span></span></span></span>，从而破坏 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>。这里的关键是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6111em;"></span><span class="mord text"><span class="mord texttt">Pre</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∪</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6111em;"></span><span class="mord text"><span class="mord texttt">Eff</span></span></span></span></span> 定义在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span> 上而策略活在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span></span></span></span> 上，两个&quot;相关性&quot;概念根本不是同一个东西。</p><p>两个指标。Ratio Performance Delta 衡量单技能相对退化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">RPD</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3324em;vertical-align:-0.9721em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">orig</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">orig</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">mod</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>分母是原任务成功率，所以<strong>当原任务本身就难（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">orig</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 很小）时 RPD 的方差会被放大</strong>，这一点在解读数字时必须记住。对整条链，先定义链上界为各技能无 OSS 时成功率之积</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">UB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.9291em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6514em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∏</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">DUBR</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">UB</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">UB</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">SR</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">chain</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>这个上界的定义值得多说一句：连乘等价于假设各技能成功事件<strong>相互独立</strong>，而&quot;独立&quot;恰恰是本文要否证的命题。因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord"><span class="mord mathrm">DUBR</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 度量的其实是&quot;偏离独立性的程度&quot;，它把 OSS 与任何其他形式的步间耦合混在一起——论文用&quot;每步复位&quot;排除了位形耦合，但没有排除物理耦合（见 §9）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：单步偏移会造成多大伤害？</strong> BOSS-C1 上，落在对角线以下（即被 OSS 负面影响）的任务比例是 BC-RESNET-RNN 68%、BC-RESNET-T 66%、BC-VIT-T 50%、OpenVLA 66%；<strong>在这些受影响的任务中</strong>，平均 RPD 为 67% / 35% / 34% / 54%。摘要直接引用了这四个数字，但没有声明它们是<strong>条件均值</strong>——只在 RPD 为正的子集上取的平均。BC-VIT-T 那一列尤其需要小心：50% 的任务变差意味着另外 50% 变好或持平，这与&quot;纯噪声&quot;的零假设并不容易区分。</p><p><strong>问题二：偏移会累积吗？</strong> BOSS-C2 用一次/两次/三次改写作三组对照，报告&quot;平均正 RPD&quot;与&quot;OSS 发生比例&quot;两条曲线，两条都随改写次数上升；作者称多次改写下所有基线的平均 RPD 超过 50%。这是全文最符合直觉、也最容易被独立复现的结论。</p><p><strong>问题三：整条链上损失多少？</strong> BOSS-C3 的 10 条三技能链上 DUBR 普遍为正且较高。作者如实说明 BC-RESNET-RNN 有几条链的 DUBR 显示为 0%，原因是它的链上界本身就是 0——即无 OSS 时它也做不成。</p><p><strong>问题四：加数据能解决吗？</strong> 这是全文最有价值的负结果。Table I 比较 Setup A（原始演示训练）与 Setup B（57,000 条增广演示训练），都在受 OSS 影响的技能上评测：BC-RESNET-RNN 0.25→0.31（改善 0.06），BC-RESNET-T 0.67→0.54，BC-VIT-T 0.74→0.64，OpenVLA 0.54→0.54。四个模型里三个变差或持平。作者给的解释有两条：模型难以泛化到过于多样的视觉分布；以及场景-任务变体的组合爆炸使得&quot;靠数据覆盖&quot;不现实。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> 分层长程任务里，技能之间的失败常被归因于动力学衔接，但对视觉策略还存在另一个独立成因：前序技能改变了符号上无关、视觉上可见的谓词。论文把它形式化为 OSS，并利用 LIBERO 的 PDDL 描述做出可批量生成 OSS 场景的 RAMG，构成三级难度的 BOSS 基准。四个主流模仿学习方法（三种 BC + OpenVLA）在单步改写下就有一半到三分之二的任务退化，且退化随改写次数累积。用 RAMG 把演示扩到 30 倍（轨迹不变、只改视觉）之后，四个模型里三个反而变差，说明这不是靠数据量能解决的问题。基准的形式化清晰，但关键统计量是在&quot;受影响子集&quot;上取的条件均值，且改写同时改变了像素与物理，两者未被分离。</p><p><strong>3 句话版。</strong> 符号规划的&quot;无关谓词&quot;对视觉策略并不无关，这是技能链的一个系统性失效模式。BOSS 用 PDDL 改写把它变成可批量生成、可量化的三级基准。视觉多样化的数据增广被实验否定，指向需要算法层面的解法。</p><p><strong>1 句话版。</strong> 把&quot;符号相关性&quot;和&quot;感知相关性&quot;分开，就能解释为什么单独测好好的技能一串起来就崩。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>整篇论文建立在一条等式上：<strong>符号上无关 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">⇒</span></span></span></span> 物理上无关，因而观测到的退化只能归因于视觉分布偏移</strong>。这条假设在 RAMG 的三类改写下都值得怀疑。往碗里放一个土豆改变的不只是像素：碗的质量、质心、可抓握的边缘高度、被土豆遮挡的部分都变了；把抽屉打开改变的是场景的碰撞几何，机械臂的可行路径随之改变；往区域里加入新物体则同时引入了遮挡与潜在碰撞。RAMG 的约束只保证新改写不违反 <code>Pre</code>/<code>Eff</code> 的<strong>符号可行性</strong>，并不保证运动学与接触动力学不变。</p><p>如果这条假设不成立，论文的核心命名就出了问题：观测到的退化里有多大比例真的是&quot;观测空间&quot;的问题，而不是&quot;任务确实变难了&quot;，无从判断。论文为它提供的证据只有 BOSS-C3 里的&quot;每步复位机器人&quot;，那只排除了<strong>起始位形</strong>这一种耦合，没有排除接触几何与遮挡。缺的证据是一个把像素变化与物理变化分离开的对照组。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需 LIBERO 与一块 GPU：用 RAMG 生成两类改写，一类是<strong>物理惰性</strong>的（只改已有物体的颜色/纹理，或把新物体放在机械臂工作空间之外但仍在相机视野内），一类是论文原本的三类改写。在同一批 44 个技能上重训同一个 BC-RESNET-T，测两类改写下的 RPD。</p><p>同时做一个<strong>安慰剂对照</strong>：用不同随机种子把<strong>完全未改写</strong>的任务当作&quot;改写版&quot;再跑一遍，按同样公式算 RPD，并同样只在正值子集上取均值。判据：如果物理惰性改写的平均正 RPD 明显高于安慰剂对照，OSS 作为纯感知现象成立；如果两者接近，而只有物理性改写掉分，那么论文测到的主要是任务难度变化而非观测空间偏移。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，有两条独立的攻击线，任何一条成立都足以削弱主结论。</p><p><strong>第一条是统计的。</strong> 头条数字（67% / 35% / 34% / 54%）是在 RPD 为正的子集上取的条件均值，而该子集只占 50%–68% 的任务；RPD 又以原始成功率为分母，对低成功率任务极不稳定；实验只有三个种子。在这种设定下，即使真实效应为零，&quot;正 RPD 子集的均值&quot;也会是一个明显大于零的数——这正是 §10 那个安慰剂对照要测的量。论文自己承认&quot;负 RPD 可能来自模仿学习模型的随机性&quot;，却没有把这份随机性量化成噪声底。BC-VIT-T 恰好 50% 的受影响比例是最提示性的信号。</p><p><strong>第二条是设定的。</strong> 为了与 OpenVLA 对齐，BC 基线被<strong>去掉了腕部相机</strong>，而腕部视角恰恰是对远处场景变化最不敏感的那一路观测——LIBERO 的默认 BC 配置是双视角。这个选择在方向上系统性放大了 OSS。干净的反例实验是：给三个 BC 基线加回腕部相机，重跑 BOSS-C1。如果 RPD 大幅收窄，那么结论应当改写为&quot;OSS 严重程度强依赖于观测配置&quot;，而不是&quot;分层范式有系统性上限&quot;。此外，数据增广那组实验里轨迹被原样重放，因此 57,000 条演示没有引入任何新的动作信息，&quot;增广无效&quot;这一结论的适用范围也应相应收窄。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文把 OSS 当作一个需要被&quot;修复&quot;的鲁棒性缺陷，这个 framing 会自然导向&quot;更强的视觉骨干 / 更多数据 / 更好的域随机化&quot;这类增量工作，而 Table I 已经暗示这条路收益有限。</p><p>值得换的 framing 是：<strong>让技能显式声明它被许可依赖哪些像素</strong>。(a) 驱动这个想法的局限是，当前技能只有符号层的 <code>Pre</code>/<code>Eff</code> 契约，感知层没有任何契约，于是规划器无法在链接之前判断两个技能是否兼容。(b) 可借鉴的工具来自因果表示学习与不变风险最小化：RAMG 本身就是一台<strong>干预生成器</strong>，它能以零成本产生&quot;只改某个谓词、其余不变&quot;的成对数据，这正是估计&quot;策略输出对某谓词的因果依赖&quot;所需要的实验设计——这类干预数据在真实机器人上通常拿不到，是这个模拟基准被低估的价值。(c) 第一个实验：对每个技能，用 RAMG 的成对干预数据估计一张<strong>谓词敏感度图</strong>，把敏感但不在 <code>Pre</code>∪<code>Eff</code> 中的谓词区域在训练与推理时都用分割掩码中和掉（涂成背景色或用邻域 inpaint），然后重测 BOSS-C1 的 RPD。如果掩码能显著回收 RPD，那么&quot;感知契约 + 转移时的视觉抽象算子&quot;就构成了一个不需要重训、可插入任意规划器的解法；如果不能，说明策略依赖的是全局上下文而非局部谓词区域，那么问题的性质要重新定义。相应地，规划器可以在排序技能时把感知契约的冲突作为一项显式代价，这是当前 TAMP 与 LLM 规划器都还没有的接口。</p>',50)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
